export interface WaveDisplayOptions {
  width: number;
  height: number;
  label: string;
  backgroundColor?: string;
  gridColor?: string;
}

export class WaveDisplay {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private container: HTMLElement;
  private options: WaveDisplayOptions;

  constructor(options: WaveDisplayOptions) {
    this.options = {
      backgroundColor: "transparent",
      gridColor: "rgba(255, 255, 255, 0.1)",
      ...options,
    };
    this.container = this.createContainer();
    this.canvas = this.container.querySelector("canvas")!;
    this.ctx = this.canvas.getContext("2d", { alpha: true })!; // Alpha true for layering
    this.setupCanvas();
  }

  private createContainer(): HTMLElement {
    const wrapper = document.createElement("div");
    wrapper.className = "wave-display";
    const canvas = document.createElement("canvas");
    canvas.className = "wave-canvas";
    wrapper.appendChild(canvas);
    return wrapper;
  }

  private setupCanvas(): void {
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = this.options.width * dpr;
    this.canvas.height = this.options.height * dpr;
    this.canvas.style.width = this.options.width + "px";
    this.canvas.style.height = this.options.height + "px";
    this.ctx.scale(dpr, dpr);
  }

  clear(): void {
    this.ctx.clearRect(0, 0, this.options.width, this.options.height);
  }

  drawGrid(): void {
    const { width, height } = this.options;
    const centerY = height / 2;

    // Draw Label (Small, corner tech text)
    this.ctx.font = "700 16px 'Segoe UI', sans-serif";
    this.ctx.fillStyle = "rgba(255, 255, 255, 0.3)";
    this.ctx.textAlign = "center";
    this.ctx.fillText(this.options.label, 460, 15);

    this.ctx.lineWidth = 1;
    this.ctx.strokeStyle = this.options.gridColor!;

    // Grid Lines (Vertical divisions)
    this.ctx.beginPath();
    const divisions = 8;
    for (let i = 1; i < divisions; i++) {
      const x = (width / divisions) * i;
      this.ctx.moveTo(x, 0);
      this.ctx.lineTo(x, height);
    }

    // Center Axis
    this.ctx.moveTo(0, centerY);
    this.ctx.lineTo(width, centerY);

    this.ctx.stroke();

    // Subtle border bottom for separation if stacked
    this.ctx.strokeStyle = "rgba(255,255,255,0.05)";
    this.ctx.beginPath();
    this.ctx.moveTo(0, height);
    this.ctx.lineTo(width, height);
    this.ctx.stroke();
  }

  drawWave(
    frequency: number,
    currentTime: number,
    amplitude: number = 0.8,
    color: string,
    lineWidth: number = 2,
  ): void {
    const { width, height } = this.options;
    const centerY = height / 2;
    const margin = 20;
    const drawHeight = height - 2 * margin;

    // Outer glow for the "laser" look
    this.ctx.shadowBlur = 8;
    this.ctx.shadowColor = color;

    this.ctx.strokeStyle = color;
    this.ctx.lineWidth = lineWidth;
    this.ctx.beginPath();

    // Prevent sharp edges at start/end
    this.ctx.lineCap = "round";
    this.ctx.lineJoin = "round";

    const numPoints = width; // Optimization: 1 point per pixel is usually enough
    const displayDuration = 0.008;

    for (let i = 0; i <= numPoints; i++) {
      const pixelX = (i / numPoints) * width;
      const timeOffset = (pixelX / width) * displayDuration;
      const absoluteTime = currentTime - displayDuration + timeOffset;

      const phase = 2 * Math.PI * frequency * absoluteTime;
      const value = Math.sin(phase);
      const y = centerY - (value * amplitude * drawHeight) / 2;

      if (i === 0) this.ctx.moveTo(pixelX, y);
      else this.ctx.lineTo(pixelX, y);
    }

    this.ctx.stroke();

    // Reset shadow for other draws
    this.ctx.shadowBlur = 0;
  }

  drawSamplePoints(
    samples: Array<{ x: number; y: number }>,
    color: string,
    showConnections: boolean = true, // Enabled by default now
  ): void {
    if (samples.length === 0) return;
    const centerY = this.options.height / 2;

    // 1. Draw connecting lines (Step/Linear reconstruction look)
    if (showConnections) {
      this.ctx.strokeStyle = color;
      this.ctx.lineWidth = 1.5;
      this.ctx.globalAlpha = 0.6; // Higher contrast for connections
      this.ctx.beginPath();
      samples.forEach((point, i) => {
        if (i === 0) {
          this.ctx.moveTo(point.x, point.y);
        } else {
          // Linear connection
          this.ctx.lineTo(point.x, point.y);
        }
      });
      this.ctx.stroke();
      this.ctx.globalAlpha = 1.0;
    }

    // 2. Draw vertical stems
    samples.forEach((point) => {
      this.ctx.strokeStyle = color;
      this.ctx.globalAlpha = 0.2;
      this.ctx.lineWidth = 1;
      this.ctx.beginPath();
      this.ctx.moveTo(point.x, centerY);
      this.ctx.lineTo(point.x, point.y);
      this.ctx.stroke();
    });

    // 3. Draw sample dots with glow
    samples.forEach((point) => {
      this.ctx.globalAlpha = 1.0;
      this.ctx.shadowBlur = 6;
      this.ctx.shadowColor = color;
      this.ctx.fillStyle = color;
      this.ctx.beginPath();
      this.ctx.arc(point.x, point.y, 3, 0, 2 * Math.PI);
      this.ctx.fill();
    });
    this.ctx.shadowBlur = 0;
  }
  getElement(): HTMLElement {
    return this.container;
  }
}
