import { SignalData, AliasingInfo } from "../types";

export class DSPUtils {
  static getSamples(
    frequency: number,
    sampleRate: number,
    windowDuration: number = 0.1,
  ): SignalData {
    const numSamples = Math.floor(sampleRate * windowDuration);
    const samples = new Float32Array(numSamples);
    const sampleTimes = new Float32Array(numSamples);

    for (let i = 0; i < numSamples; i++) {
      const t = i / sampleRate;
      samples[i] = Math.sin(2 * Math.PI * frequency * t);
      sampleTimes[i] = t;
    }

    return { samples, sampleTimes, duration: windowDuration };
  }

  static getAliasedFrequency(freq: number, sampleRate: number): number {
    const nyquist = sampleRate / 2;
    if (freq <= nyquist) {
      return freq;
    }

    // Frequency folding formula
    const k = Math.floor((freq + nyquist) / sampleRate);
    const aliasedFreq = Math.abs(freq - k * sampleRate);

    return aliasedFreq;
  }

  static getAliasingInfo(frequency: number, sampleRate: number): AliasingInfo {
    const nyquistFreq = sampleRate / 2;
    const isAliasing = frequency > nyquistFreq;
    const aliasedFreq = this.getAliasedFrequency(frequency, sampleRate);

    return { nyquistFreq, isAliasing, aliasedFreq };
  }

  static sinc(x: number): number {
    if (Math.abs(x) < 1e-10) return 1.0;
    const piX = Math.PI * x;
    return Math.sin(piX) / piX;
  }

  static reconstructSignal(
    samples: Float32Array,
    sampleTimes: Float32Array,
    t: number,
    sampleRate: number,
  ): number {
    let sum = 0;
    const Ts = 1 / sampleRate;

    for (let i = 0; i < samples.length; i++) {
      const ti = sampleTimes[i];
      sum += samples[i] * this.sinc((t - ti) / Ts);
    }

    return sum;
  }
  // In dsp.ts - replace generateAudioForPlayback
  // In dsp.ts

  static generateAudioForPlayback(
    frequency: number,
    sampleRate: number,
    duration: number,
  ): Float32Array {
    // 1. Setup standard playback parameters
    const playbackRate = 44100;
    const numSamples = Math.floor(playbackRate * duration);
    const buffer = new Float32Array(numSamples);
    if (frequency % (sampleRate / 2) == 0) {
      return buffer;
    }
    // 2. Calculate the Aliased Frequency (The "Reconstructed" frequency)
    // We use the same math as the visualizer to ensure audio/visual match.
    // k is the integer number of sample rates we are away from the input frequency.
    const k = Math.round(frequency / sampleRate);

    // delta is the difference between input frequency and the nearest multiple of fs.
    const delta = frequency - k * sampleRate;

    const aliasedFreq = Math.abs(delta);

    // 3. Handle Phase Inversion
    // If the alias comes from a "negative" frequency wrap (delta is negative),
    // the reconstructed wave is inverted (phase flip).
    const phaseSign = delta === 0 ? 1 : Math.sign(delta);

    // 4. Generate the wave directly at 44.1kHz
    // This is mathematically equivalent to "oversampling with an ideal reconstruction filter".
    // It removes all ringing artifacts and ensures the buffer is compatible with the browser.
    for (let i = 0; i < numSamples; i++) {
      const t = i / playbackRate;
      buffer[i] = phaseSign * Math.sin(2 * Math.PI * aliasedFreq * t);
    }

    return buffer;
  }
}
