import { KnobConfig } from "../types";

export class Knob {
  private container: HTMLElement;
  private svg: SVGElement;
  private value: number;
  private config: KnobConfig;
  private onChange: (value: number) => void;
  private isDragging: boolean = false;
  private startY: number = 0;
  private startValue: number = 0;
  private indicator: SVGElement;

  // In Knob.ts constructor - store default value
  constructor(config: KnobConfig, onChange: (value: number) => void) {
    this.config = {
      ...config,
      defaultValue: config.defaultValue ?? config.value, // Use provided default or initial value
    };
    this.value = config.value;
    this.onChange = onChange;
    this.container = this.createKnob();
    this.svg = this.container.querySelector("svg")!;
    this.indicator = this.svg.querySelector(".knob-indicator")!;
    this.updateVisuals();
    this.attachEventListeners();
  }

  private createKnob(): HTMLElement {
    const wrapper = document.createElement("div");
    wrapper.className = "knob-wrapper";

    const knobContainer = document.createElement("div");
    knobContainer.className = "knob-container";

    // Create SVG knob
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("viewBox", "0 0 100 100");
    svg.setAttribute("class", "knob-svg");

    // Outer rim/shadow
    const outerCircle = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "circle",
    );
    outerCircle.setAttribute("cx", "50");
    outerCircle.setAttribute("cy", "50");
    outerCircle.setAttribute("r", "48");
    outerCircle.setAttribute("class", "knob-outer");

    // Main knob body
    const mainCircle = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "circle",
    );
    mainCircle.setAttribute("cx", "50");
    mainCircle.setAttribute("cy", "50");
    mainCircle.setAttribute("r", "42");
    mainCircle.setAttribute("class", "knob-body");

    // Inner gradient circle for depth
    const innerGradient = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "circle",
    );
    innerGradient.setAttribute("cx", "50");
    innerGradient.setAttribute("cy", "50");
    innerGradient.setAttribute("r", "38");
    innerGradient.setAttribute("class", "knob-inner");

    // Value arc track (background)
    const arcTrack = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "path",
    );
    arcTrack.setAttribute("class", "knob-arc-track");
    arcTrack.setAttribute("d", this.describeArc(50, 50, 45, 210, 330));
    arcTrack.setAttribute("fill", "none");

    // Value arc (progress indicator)
    const arcValue = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "path",
    );
    arcValue.setAttribute("class", "knob-arc-value");
    arcValue.setAttribute("fill", "none");

    // Indicator line/dot
    const indicatorGroup = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "g",
    );
    indicatorGroup.setAttribute("class", "knob-indicator");

    const indicatorLine = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "line",
    );
    indicatorLine.setAttribute("x1", "50");
    indicatorLine.setAttribute("y1", "18");
    indicatorLine.setAttribute("x2", "50");
    indicatorLine.setAttribute("y2", "32");
    indicatorLine.setAttribute("stroke-linecap", "round");

    const indicatorDot = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "circle",
    );
    indicatorDot.setAttribute("cx", "50");
    indicatorDot.setAttribute("cy", "25");
    indicatorDot.setAttribute("r", "4");

    indicatorGroup.appendChild(indicatorLine);
    indicatorGroup.appendChild(indicatorDot);

    svg.appendChild(outerCircle);
    svg.appendChild(mainCircle);
    svg.appendChild(innerGradient);
    svg.appendChild(arcTrack);
    svg.appendChild(arcValue);
    svg.appendChild(indicatorGroup);

    knobContainer.appendChild(svg);

    // Label
    const label = document.createElement("div");
    label.className = "knob-label";
    label.textContent = this.config.label;

    // Value display
    const valueDisplay = document.createElement("div");
    valueDisplay.className = "knob-value";
    valueDisplay.textContent = `${this.value}${this.config.unit}`;

    wrapper.appendChild(knobContainer);
    wrapper.appendChild(valueDisplay);
    wrapper.appendChild(label);

    return wrapper;
  }

  private describeArc(
    x: number,
    y: number,
    radius: number,
    startAngle: number,
    endAngle: number,
  ): string {
    const start = this.polarToCartesian(x, y, radius, endAngle);
    const end = this.polarToCartesian(x, y, radius, startAngle);
    const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
    return `M ${start.x} ${start.y} A ${radius} ${radius} 0 ${largeArcFlag} 0 ${end.x} ${end.y}`;
  }

  private polarToCartesian(
    centerX: number,
    centerY: number,
    radius: number,
    angleInDegrees: number,
  ) {
    const angleInRadians = ((angleInDegrees - 90) * Math.PI) / 180.0;
    return {
      x: centerX + radius * Math.cos(angleInRadians),
      y: centerY + radius * Math.sin(angleInRadians),
    };
  }

  private getAngle(): number {
    const percent =
      (this.value - this.config.min) / (this.config.max - this.config.min);
    return 210 + percent * 300; // 210° to 510° (300° range)
  }

  private updateVisuals(): void {
    const angle = this.getAngle();

    // Update indicator rotation
    this.indicator.setAttribute("transform", `rotate(${angle} 50 50)`);

    // Update value arc
    const arcValue = this.svg.querySelector(
      ".knob-arc-value",
    ) as SVGPathElement;
    if (arcValue) {
      arcValue.setAttribute("d", this.describeArc(50, 50, 45, 210, angle));
    }

    // Update value display
    const valueDisplay = this.container.querySelector(
      ".knob-value",
    ) as HTMLElement;
    if (valueDisplay) {
      const displayValue =
        this.config.unit === "Hz" && this.value >= 1000
          ? `${(this.value / 1000).toFixed(1)}k${this.config.unit}`
          : `${Math.round(this.value)}${this.config.unit}`;
      valueDisplay.textContent = displayValue;
    }
  }
  // In Knob.ts - add reset on double-click in attachEventListeners method
  private attachEventListeners(): void {
    const knobSvg = this.svg;

    // Double-click to reset to default
    knobSvg.addEventListener("dblclick", (e) => {
      e.preventDefault();
      this.setValue(this.config.value); // Reset to initial value
      this.onChange(this.value);
    });

    // Middle-click to reset to default
    knobSvg.addEventListener("mousedown", (e) => {
      if (e.button === 1) {
        // Middle mouse button
        e.preventDefault();
        this.setValue(this.config.value);
        this.onChange(this.value);
        return;
      }
    });

    // In Knob.ts - update the double-click handler to use defaultValue
    knobSvg.addEventListener("dblclick", (e) => {
      e.preventDefault();
      this.setValue(this.config.defaultValue ?? this.config.value);
      this.onChange(this.value);
    });

    // Middle-click to reset to default
    knobSvg.addEventListener("mousedown", (e) => {
      if (e.button === 1) {
        // Middle mouse button
        e.preventDefault();
        this.setValue(this.config.defaultValue ?? this.config.value);
        this.onChange(this.value);
        return;
      }
    });
    const onMouseDown = (e: MouseEvent) => {
      if (e.button !== 0) return; // Only left click for dragging
      e.preventDefault();
      this.isDragging = true;
      this.startY = e.clientY;
      this.startValue = this.value;
      document.body.style.cursor = "ns-resize";
    };

    const onMouseMove = (e: MouseEvent) => {
      if (!this.isDragging) return;

      const deltaY = this.startY - e.clientY;
      const sensitivity = 0.5;
      const range = this.config.max - this.config.min;
      const delta = (deltaY * sensitivity * range) / 200;

      let newValue = this.startValue + delta;
      newValue = Math.max(this.config.min, Math.min(this.config.max, newValue));

      // Snap to step
      newValue = Math.round(newValue / this.config.step) * this.config.step;

      if (newValue !== this.value) {
        this.value = newValue;
        this.updateVisuals();
        this.onChange(this.value);
      }
    };

    const onMouseUp = () => {
      this.isDragging = false;
      document.body.style.cursor = "";
    };

    knobSvg.addEventListener("mousedown", onMouseDown);
    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("mouseup", onMouseUp);

    // Touch support
    knobSvg.addEventListener("touchstart", (e) => {
      e.preventDefault();
      this.isDragging = true;
      this.startY = e.touches[0].clientY;
      this.startValue = this.value;
    });

    document.addEventListener("touchmove", (e) => {
      if (!this.isDragging) return;

      const deltaY = this.startY - e.touches[0].clientY;
      const sensitivity = 0.5;
      const range = this.config.max - this.config.min;
      const delta = (deltaY * sensitivity * range) / 200;

      let newValue = this.startValue + delta;
      newValue = Math.max(this.config.min, Math.min(this.config.max, newValue));
      newValue = Math.round(newValue / this.config.step) * this.config.step;

      if (newValue !== this.value) {
        this.value = newValue;
        this.updateVisuals();
        this.onChange(this.value);
      }
    });

    document.addEventListener("touchend", () => {
      this.isDragging = false;
    });
  }

  getValue(): number {
    return this.value;
  }

  setValue(value: number): void {
    this.value = Math.max(this.config.min, Math.min(this.config.max, value));
    this.value = Math.round(this.value / this.config.step) * this.config.step;
    this.updateVisuals();
  }

  getElement(): HTMLElement {
    return this.container;
  }
}
