export interface InfoItem {
  label: string;
  value: string;
  warning?: boolean;
}

export class InfoPanel {
  private container: HTMLElement;
  private items: Map<string, HTMLElement> = new Map();

  constructor(items: InfoItem[]) {
    this.container = this.createPanel(items);
  }

  private createPanel(items: InfoItem[]): HTMLElement {
    const panel = document.createElement('div');
    panel.className = 'info-panel';

    items.forEach((item) => {
      const itemElement = this.createItem(item);
      this.items.set(item.label, itemElement);
      panel.appendChild(itemElement);
    });

    return panel;
  }

  private createItem(item: InfoItem): HTMLElement {
    const wrapper = document.createElement('div');
    wrapper.className = 'info-item';

    const label = document.createElement('div');
    label.className = 'info-item-label';
    label.textContent = item.label;

    const value = document.createElement('div');
    value.className = 'info-item-value';
    if (item.warning) {
      value.classList.add('warning');
    }
    value.textContent = item.value;

    wrapper.appendChild(label);
    wrapper.appendChild(value);

    return wrapper;
  }

  updateItem(label: string, value: string, warning: boolean = false): void {
    const item = this.items.get(label);
    if (item) {
      const valueElement = item.querySelector('.info-item-value');
      if (valueElement) {
        valueElement.textContent = value;
        if (warning) {
          valueElement.classList.add('warning');
        } else {
          valueElement.classList.remove('warning');
        }
      }
    }
  }

  getElement(): HTMLElement {
    return this.container;
  }
}
