import { Knob } from "./components/Knob";
import { Button } from "./components/Button";
import { WaveDisplay } from "./components/WaveDisplay";
import { InfoPanel } from "./components/InfoPanel";
import { DSPUtils } from "./utils/dsp";
import { AudioEngine } from "./utils/audio";
import { KnobConfig } from "./types";

export class AliasingVisualizer {
  private frequency: number = 1000;
  private sampleRate: number = 2000;
  private speed: number = 0.1;
  private audioEngine: AudioEngine;

  private frequencyKnob!: Knob;
  private sampleRateKnob!: Knob;
  private playButton!: Button;
  private infoPanel!: InfoPanel;

  private originalDisplay!: WaveDisplay;
  private sampledDisplay!: WaveDisplay;
  private reconstructedDisplay!: WaveDisplay;

  private container: HTMLElement;
  private isPlaying: boolean = false;
  private animationId: number | null = null;

  // Animation timing
  private time: number = 0;
  private lastTimestamp: number = 0;

  constructor(containerId: string) {
    const element = document.getElementById(containerId);
    if (!element) {
      throw new Error(`Container with id "${containerId}" not found`);
    }
    this.container = element;
    this.audioEngine = new AudioEngine();
    this.init();
  }

  private init(): void {
    this.createUI();
    this.startAnimation();
  }

  private createUI(): void {
    // 1. WAVE DISPLAYS
    const displaysContainer = document.createElement("div");
    displaysContainer.className = "displays-container";

    // Increase height significantly for the "Big Screen" look
    const displayWidth = Math.min(960, window.innerWidth - 60);
    const displayHeight = 220; // Much taller than before

    // Common options for VST look
    const displayOpts = {
      width: displayWidth,
      height: displayHeight,
      backgroundColor: "transparent", // Let CSS handle the screen background
      gridColor: "rgba(255, 255, 255, 0.05)",
    };

    this.originalDisplay = new WaveDisplay({
      ...displayOpts,
      label: "ORIGINAL ANALOG",
    });
    this.sampledDisplay = new WaveDisplay({
      ...displayOpts,
      label: "SAMPLING STAGE",
    });
    this.reconstructedDisplay = new WaveDisplay({
      ...displayOpts,
      label: "DIGITAL RECONSTRUCTION",
    });

    displaysContainer.appendChild(this.originalDisplay.getElement());
    displaysContainer.appendChild(this.sampledDisplay.getElement());
    displaysContainer.appendChild(this.reconstructedDisplay.getElement());

    // 2. CONTROLS DECK
    const controlsContainer = document.createElement("div");
    controlsContainer.className = "controls-container";

    // Left: Info Panel (Digital Readout)
    this.infoPanel = new InfoPanel([
      { label: "NYQUIST", value: "1000 Hz" },
      { label: "ALIAS", value: "—" },
    ]);

    // Center: Knobs
    const knobsWrapper = document.createElement("div");
    knobsWrapper.className = "knobs-wrapper";

    const freqConfig: KnobConfig = {
      min: 10,
      max: 10000,
      value: this.frequency,
      step: 100,
      label: "INPUT FREQ",
      unit: "Hz",
    };

    const sampleConfig: KnobConfig = {
      min: 500,
      max: 20000,
      value: this.sampleRate,
      step: 100,
      label: "SAMPLE RATE",
      unit: "Hz",
    };

    this.frequencyKnob = new Knob(freqConfig, (value) => {
      this.frequency = value;
      this.time = 0;
      this.updateInfoPanel();
      this.updateAudio();
    });

    this.sampleRateKnob = new Knob(sampleConfig, (value) => {
      this.sampleRate = value;
      this.time = 0;
      this.updateInfoPanel();
      this.updateAudio();
    });

    knobsWrapper.appendChild(this.frequencyKnob.getElement());
    knobsWrapper.appendChild(this.sampleRateKnob.getElement());

    // Right: Play Button
    this.playButton = new Button("Play Audio", () => this.toggleAudio());

    // Assemble Control Deck
    controlsContainer.appendChild(this.infoPanel.getElement());
    controlsContainer.appendChild(knobsWrapper);
    controlsContainer.appendChild(this.playButton.getElement());

    // 3. FINAL ASSEMBLY
    this.container.appendChild(displaysContainer);
    this.container.appendChild(controlsContainer);

    this.updateInfoPanel();
  }

  // ... [Animation Loop and Render methods remain largely the same, but note colors below] ...

  private startAnimation(): void {
    const animate = (timestamp: number) => {
      if (this.lastTimestamp === 0) this.lastTimestamp = timestamp;
      const deltaTime = (timestamp - this.lastTimestamp) / 1000;
      this.lastTimestamp = timestamp;

      if (this.speed > 0) {
        this.time += deltaTime * this.speed * 0.005;
      }
      this.updateAnimation();
      this.animationId = requestAnimationFrame(animate);
    };
    this.animationId = requestAnimationFrame(animate);
  }

  private updateAnimation(): void {
    this.renderDisplays();
  }

  private renderDisplays(): void {
    this.renderOriginalSignal();
    this.renderSampledSignal();
    this.renderReconstructedSignal();
  }

  private renderOriginalSignal(): void {
    this.originalDisplay.clear();
    this.originalDisplay.drawGrid();
    // Use the Cyan Accent Color
    this.originalDisplay.drawWave(this.frequency, this.time, 0.8, "#52cffe", 2);
  }

  private renderSampledSignal(): void {
    this.sampledDisplay.clear();
    this.sampledDisplay.drawGrid();

    // Background ghost wave remains very faint
    this.sampledDisplay.drawWave(
      this.frequency,
      this.time,
      0.8,
      "rgba(82, 207, 254, 0.05)",
      1,
    );

    const samples = this.calculateSamplePoints(this.frequency);

    // Higher contrast color for the "Sampling Stage" (Vibrant Pink/Red)
    // The third argument 'true' ensures connection lines are drawn
    this.sampledDisplay.drawSamplePoints(samples, "#ff4d6d", true);
  }

  private renderReconstructedSignal(): void {
    this.reconstructedDisplay.clear();
    this.reconstructedDisplay.drawGrid();

    const k = Math.round(this.frequency / this.sampleRate);
    const delta = this.frequency - k * this.sampleRate;
    const reconstructedFreq = Math.abs(delta);
    const phaseSign = Math.sign(delta) || 1;

    // Use a Golden/Yellow for reconstruction to differentiate
    this.reconstructedDisplay.drawWave(
      reconstructedFreq,
      this.time,
      0.8 * phaseSign,
      "#ffd700",
      2,
    );

    const samples = this.calculateSamplePoints(this.frequency);
    this.reconstructedDisplay.drawSamplePoints(samples, "#ffd700", false);
  }

  // ... [Rest of calculation logic remains identical] ...

  private calculateSamplePoints(
    frequency: number,
  ): Array<{ x: number; y: number }> {
    const canvas = this.originalDisplay.getElement().querySelector("canvas")!;
    const width = canvas.offsetWidth;
    const height = canvas.offsetHeight;
    const centerY = height / 2;
    const margin = 20; // Increased margin for visual breathing room
    const drawHeight = height - 2 * margin;

    const points: Array<{ x: number; y: number }> = [];
    const displayDuration = 0.008;

    const startTime = this.time - displayDuration;
    const endTime = this.time;
    const startSampleIndex = Math.ceil(startTime * this.sampleRate);

    let i = startSampleIndex;
    while (true) {
      const absoluteTime = i / this.sampleRate;
      if (absoluteTime > endTime) break;

      const timeInWindow = absoluteTime - startTime;
      const x = (timeInWindow / displayDuration) * width;
      const phase = 2 * Math.PI * frequency * absoluteTime;
      const value = Math.sin(phase);
      const y = centerY - (value * 0.8 * drawHeight) / 2;

      points.push({ x, y });
      i++;
    }
    return points;
  }

  private updateInfoPanel(): void {
    const info = DSPUtils.getAliasingInfo(this.frequency, this.sampleRate);
    const nyquistText =
      info.nyquistFreq >= 1000
        ? `${(info.nyquistFreq / 1000).toFixed(1)}kHz`
        : `${info.nyquistFreq.toFixed(0)}Hz`;

    this.infoPanel.updateItem("NYQUIST", nyquistText);

    if (info.isAliasing) {
      const aliasText =
        info.aliasedFreq >= 1000
          ? `${(info.aliasedFreq / 1000).toFixed(1)}kHz`
          : `${info.aliasedFreq.toFixed(0)}Hz`;
      this.infoPanel.updateItem("ALIAS", aliasText, true);
    } else {
      this.infoPanel.updateItem("ALIAS", "CLEAN", false);
    }
  }

  private toggleAudio(): void {
    if (this.isPlaying) {
      this.stopAudio();
    } else {
      this.playAudio();
    }
  }

  private playAudio(): void {
    const audioData = DSPUtils.generateAudioForPlayback(
      this.frequency,
      this.sampleRate,
      2.0,
    );
    this.audioEngine.play(audioData, this.frequency, this.sampleRate);
    this.isPlaying = true;
    this.playButton.setText("STOP AUDIO");
    this.playButton.setActive(true);
  }

  private updateAudio(): void {
    if (this.isPlaying) {
      const audioData = DSPUtils.generateAudioForPlayback(
        this.frequency,
        this.sampleRate,
        2.0,
      );
      this.audioEngine.updateAudio(audioData, this.frequency, this.sampleRate);
    }
  }

  private stopAudio(): void {
    this.audioEngine.stop();
    this.isPlaying = false;
    this.playButton.setText("Play Audio");
    this.playButton.setActive(false);
  }

  destroy(): void {
    if (this.animationId !== null) cancelAnimationFrame(this.animationId);
    this.audioEngine.cleanup();
  }
}
