export class AudioEngine {
  private audioContext: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  // We track the currently active source and its specific envelope (volume)
  private activeSource: AudioBufferSourceNode | null = null;
  private activeEnvelope: GainNode | null = null;

  private isPlaying: boolean = false;
  private currentFrequency: number = 0;
  private currentSampleRate: number = 0;

  private initContext(): void {
    if (!this.audioContext) {
      this.audioContext = new (
        window.AudioContext || (window as any).webkitAudioContext
      )();

      // Master gain node stays constant
      this.masterGain = this.audioContext.createGain();
      this.masterGain.gain.value = 0.25;
      this.masterGain.connect(this.audioContext.destination);
    }
    // Resume if suspended (browser autoplay policy)
    if (this.audioContext.state === "suspended") {
      this.audioContext.resume();
    }
  }

  play(audioData: Float32Array, frequency: number, sampleRate: number): void {
    this.initContext();

    if (!this.audioContext || !this.masterGain) return;

    this.currentFrequency = frequency;
    this.currentSampleRate = sampleRate;

    const playbackSampleRate = 44100;
    const now = this.audioContext.currentTime;
    const crossfadeDuration = 0.01;

    // 1. Create the NEW Source & Envelope
    const buffer = this.audioContext.createBuffer(
      1,
      audioData.length,
      playbackSampleRate,
    );
    buffer.getChannelData(0).set(audioData);

    const newSource = this.audioContext.createBufferSource();
    newSource.buffer = buffer;
    newSource.loop = true;

    const newEnvelope = this.audioContext.createGain();

    // Start silent so we can fade in
    newEnvelope.gain.setValueAtTime(0, now);

    // Connect: Source -> Envelope -> Master Gain
    newSource.connect(newEnvelope);
    newEnvelope.connect(this.masterGain);

    newSource.start(now);

    // 2. Fade IN the new source
    newEnvelope.gain.linearRampToValueAtTime(1, now + crossfadeDuration);

    // 3. Fade OUT the old source (if it exists)
    if (this.activeSource && this.activeEnvelope) {
      const oldSource = this.activeSource;
      const oldEnvelope = this.activeEnvelope;

      // Cancel any existing scheduled ramps to prevent conflicts
      oldEnvelope.gain.cancelScheduledValues(now);
      oldEnvelope.gain.setValueAtTime(oldEnvelope.gain.value, now);

      // Ramp to 0
      oldEnvelope.gain.linearRampToValueAtTime(0, now + crossfadeDuration);

      // Stop and disconnect after the fade out finishes
      oldSource.stop(now + crossfadeDuration + 0.1);
      setTimeout(
        () => {
          oldSource.disconnect();
          oldEnvelope.disconnect();
        },
        (crossfadeDuration + 0.2) * 1000,
      );
    }

    // 4. Update references
    this.activeSource = newSource;
    this.activeEnvelope = newEnvelope;
    this.isPlaying = true;
  }

  updateAudio(
    audioData: Float32Array,
    frequency: number,
    sampleRate: number,
  ): void {
    // Only update if parameters changed
    if (
      frequency === this.currentFrequency &&
      sampleRate === this.currentSampleRate
    ) {
      return;
    }

    if (this.isPlaying) {
      // The play method now handles the crossfade logic
      this.play(audioData, frequency, sampleRate);
    }
  }

  stop(): void {
    if (this.activeSource && this.activeEnvelope && this.audioContext) {
      const now = this.audioContext.currentTime;
      const fadeOutDuration = 0.1;

      // Smooth fade out before stopping completely
      this.activeEnvelope.gain.cancelScheduledValues(now);
      this.activeEnvelope.gain.setValueAtTime(
        this.activeEnvelope.gain.value,
        now,
      );
      this.activeEnvelope.gain.linearRampToValueAtTime(
        0,
        now + fadeOutDuration,
      );

      const sourceToStop = this.activeSource;
      const envelopeToStop = this.activeEnvelope;

      sourceToStop.stop(now + fadeOutDuration + 0.05);

      setTimeout(
        () => {
          sourceToStop.disconnect();
          envelopeToStop.disconnect();
        },
        (fadeOutDuration + 0.1) * 1000,
      );

      this.activeSource = null;
      this.activeEnvelope = null;
      this.isPlaying = false;
    }
  }

  getIsPlaying(): boolean {
    return this.isPlaying;
  }

  cleanup(): void {
    this.stop();
    if (this.audioContext) {
      this.audioContext.close();
      this.audioContext = null;
      this.masterGain = null;
    }
  }
}
